const StudioTile = ({studio,essential,onOpen}:{studio:CatalogStudio;essential?:boolean;onOpen:(studio:Studio)=>void}) => { const state=studioCardStatusById[studio.id]||'Not In Use'; const meta=studioStatusMeta[state]; return <button onClick={()=>onOpen(studio)} className={`group flex h-[148px] w-full min-w-0 flex-col overflow-hidden border border-slate-200 bg-white p-4 text-left shadow-sm transition hover:border-blue-300 hover:shadow-md ${essential?'items-center text-center':'items-stretch'}`} title={`${state}: ${meta.description}`}>{essential&&<div className="mb-1 flex h-8 w-8 flex-shrink-0 items-center justify-center text-blue-500"><Network size={27} strokeWidth={1.5}/></div>}<div className="min-h-0 flex-1"><h3 className="truncate text-[12px] font-semibold text-slate-800 group-hover:text-blue-600">{studio.name}</h3><p className={`mt-2 h-12 overflow-hidden text-[10px] leading-4 text-slate-500 ${essential?'mx-auto max-w-[240px]':''}`}>{studio.description}</p></div><div className="mt-2 flex w-full flex-shrink-0 items-center justify-between gap-2 border-t border-slate-50 pt-2 text-[9px]"><span className="min-w-0 truncate text-slate-400">Last submitted {studio.lastSubmitted}</span><span className={`flex flex-shrink-0 items-center gap-1 font-medium ${meta.text}`}><i className={`h-1.5 w-1.5 rounded-full ${meta.dot}`}/>{state}</span></div></button> };
const StudiosList = ({site: _site,onOpen}:{site:Site;onOpen:(studio:Studio)=>void}) => { const [query,setQuery]=useState(''); const [workspace,setWorkspace]=useState(''); const [activeOnly,setActiveOnly]=useState(false); const normalized=query.trim().toLowerCase(); return <Page><div className="-m-6 min-h-full bg-[#f7f8fa] p-5"><div className="mb-5 overflow-hidden border border-slate-200 bg-white shadow-sm"><div className="flex items-start justify-between px-4 py-3"><div><h1 className="text-xl font-semibold text-slate-900">Studios</h1><p className="mt-1 text-[10px] text-slate-500">Configure or deploy network features through the use of studios and workspaces.</p></div><div className="flex gap-2"><button className="border border-slate-200 bg-slate-100 px-3 py-2 text-[10px] font-medium text-slate-500 hover:bg-slate-200">Import Studio</button><button className="border border-slate-200 bg-slate-100 px-3 py-2 text-[10px] font-medium text-slate-500 hover:bg-slate-200">New Studio</button></div></div><div className="flex items-center gap-2 border-t border-slate-200 bg-slate-50/70 px-4 py-2.5"><span className="mr-1 text-[9px] font-semibold uppercase tracking-wide text-slate-500">Workspace</span><button className="bg-blue-600 px-3 py-2 text-[10px] font-semibold text-white hover:bg-blue-700">Create Workspace</button><select value={workspace} onChange={event=>setWorkspace(event.target.value)} aria-label="Select workspace" className="w-48 border border-slate-300 bg-white px-3 py-2 text-[10px] text-slate-600 outline-none focus:border-blue-400"><option value="">Select a workspace</option><option>WS-AIDC-018</option><option>WS-AIDC-021</option></select></div></div><section className="mb-6"><h2 className="mb-2 text-[11px] font-semibold text-slate-700">Essential Studios</h2><div className="grid grid-cols-5 gap-3">{aristaStudioGroups[0].items.map(studio=><StudioTile key={studio.id} studio={studio} essential onOpen={onOpen}/>)}</div></section><div className="mb-5 flex items-center justify-between"><div className="relative"><Search size={13} className="absolute left-2 top-1/2 -translate-y-1/2 text-slate-400"/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Search" className="w-72 border border-slate-300 bg-white py-2 pl-7 pr-3 text-[10px] outline-none focus:border-blue-400"/></div><div className="flex items-center gap-4 text-[10px] text-slate-500"><button className="flex items-center gap-1">Sort: Name (A-Z)<ChevronRight size={11} className="rotate-90"/></button><label className="flex cursor-pointer items-center gap-2"><button type="button" onClick={()=>setActiveOnly(value=>!value)} className={`relative h-6 w-10 rounded-full transition ${activeOnly?'bg-blue-600':'bg-slate-300'}`}><span className={`absolute top-1 h-4 w-4 rounded-full bg-white transition ${activeOnly?'left-5':'left-1'}`}/></button>Active Studios</label></div></div>{aristaStudioGroups.slice(1).map(group=>{ const items=group.items.filter(studio=>(!activeOnly||studioCardStatusById[studio.id]!=='Not In Use')&&(!normalized||studio.name.toLowerCase().includes(normalized)||studio.description.toLowerCase().includes(normalized))); if(!items.length)return null; const columns='grid-cols-5'; return <section key={group.title} className="mb-6"><h2 className="mb-2 text-[11px] font-semibold text-slate-700">{group.title}</h2><div className={`grid ${columns} gap-3`}>{items.map(studio=><StudioTile key={studio.id} studio={studio} onOpen={onOpen}/>)}</div></section>})}</div></Page> };
const LegacyStudiosList = ({site,onOpen}:{site:Site;onOpen:(studio:Studio)=>void}) => { const [query,setQuery]=useState(''); const filtered=studios.filter(studio=>studio.name.toLowerCase().includes(query.toLowerCase())); return <Page><div className="mb-6 flex items-start justify-between"><div><Crumb current="Studios"/><h1 className="text-2xl font-semibold text-slate-900">Studios</h1><p className="mt-1 text-xs text-slate-500">Structured, scenario-based network models for {site.name}. Business intent is outside this layer.</p></div><button className="flex items-center gap-2 rounded-lg bg-blue-600 px-4 py-2.5 text-xs font-semibold text-white"><Plus size={14}/>Create Studio</button></div><div className="mb-5 grid grid-cols-4 gap-3"><Metric label="Studios" value="5" note="2 Essential · 3 AIDC" icon={<Layers3 size={15}/>}/><Metric label="Active workspaces" value="3" note="Across structured models" icon={<GitBranch size={15}/>}/><Metric label="Network updates" value="3" note="Require workspace action" icon={<RefreshCw size={15}/>}/><Metric label="Build health" value="100%" note="No blocking errors" icon={<CheckCircle2 size={15}/>}/></div><div className="overflow-hidden rounded-xl border border-slate-200 bg-white"><div className="flex items-center justify-between border-b border-slate-100 p-4"><div className="relative"><Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Search studios..." className="w-72 rounded-lg border border-slate-200 py-2 pl-9 pr-3 text-xs outline-none focus:border-teal-400"/></div><button className="flex items-center gap-1 rounded-lg border border-slate-200 px-3 py-2 text-xs text-slate-500"><SlidersHorizontal size={13}/>Filters</button></div><table className="w-full text-left text-xs"><thead className="bg-slate-50 text-[10px] uppercase text-slate-400"><tr>{['Studio','Category','Purpose','Scope','Active Workspace','Status','Updated'].map(header=><th key={header} className="px-4 py-3 font-semibold">{header}</th>)}</tr></thead><tbody className="divide-y divide-slate-100">{filtered.map(studio=><tr key={studio.id} onClick={()=>onOpen(studio)} className="cursor-pointer hover:bg-slate-50"><td className="px-4 py-4"><p className="font-semibold text-slate-800">{studio.name}</p><p className="mt-1 font-mono text-[9px] text-slate-400">{studio.id}</p></td><td className="px-4 py-4"><Badge value={studio.category}/></td><td className="max-w-[260px] px-4 py-4 text-slate-500">{studio.description}</td><td className="px-4 py-4 text-slate-600">{studio.scope}</td><td className="px-4 py-4 font-mono text-[10px] text-blue-600">{studio.workspace}</td><td className="px-4 py-4"><Badge value={studio.status}/></td><td className="px-4 py-4 text-slate-400">{studio.updated}</td></tr>)}</tbody></table></div></Page> };
