const DetailTabs=({items,value,onChange}:{items:string[];value:string;onChange:(value:string)=>void})=><div className="flex overflow-x-auto border-b border-slate-200 px-4">{items.map(item=><button key={item} onClick={()=>onChange(item)} className={`whitespace-nowrap border-b-2 px-2.5 py-3 text-[9px] font-medium ${value===item?'border-blue-500 text-blue-700':'border-transparent text-slate-400 hover:text-slate-700'}`}>{item}</button>)}</div>;
const Pair=({label,value,mono=false}:{label:string;value:React.ReactNode;mono?:boolean})=><div className="flex items-start justify-between gap-3 border-b border-slate-100 py-2.5 text-[9px] last:border-0"><span className="text-slate-400">{label}</span><span className={`max-w-[65%] text-right font-medium text-slate-700 ${mono?'font-mono':''}`}>{value}</span></div>;
const EmptyRows=({message}:{message:string})=><div className="py-16 text-center text-[10px] text-slate-400">{message}</div>;

const WorkspacesPage=({initialWorkspaceId}:{initialWorkspaceId?:string})=>{
 const [query,setQuery]=useState('');
 const [reviewId,setReviewId]=useState<string|null>(initialWorkspaceId||null);
 const [checked,setChecked]=useState<string[]>([]);
 const [expandedDevice,setExpandedDevice]=useState<string|null>(null);
 const statusOf=(item:WorkspaceRecord):'Pending'|'Submitted'|'Abandoned'=>item.state==='Submitted'?'Submitted':item.state==='Abandoned'?'Abandoned':'Pending';
 const modifiedBy:Record<string,string>={'WS-AIDC-021':'Mina Chen','WS-AIDC-018':'Evan Brooks','WS-AIDC-014':'Mina Chen','WS-AIDC-013':'Jordan Lee'};
 const descriptions:Record<string,string>={'WS-AIDC-021':'Prepare the remaining ten planned AIDC switches while reviewing configuration for six currently mapped devices.','WS-AIDC-018':'Register the six current AIDC Fabric devices and their observed 400G links.','WS-AIDC-014':'Submitted baseline configuration for the six mapped AIDC Fabric devices.','WS-AIDC-013':'Correct the GPU Leaf baseline after resolving validation and assignment conflicts.'};
 const filtered=lifecycleWorkspaces.filter(item=>`${item.id} ${item.name} ${item.owner} ${modifiedBy[item.id]||''}`.toLowerCase().includes(query.toLowerCase()));
 const yourOpen=filtered.filter(item=>statusOf(item)==='Pending'&&item.id!=='WS-AIDC-013');
 const otherOpen=filtered.filter(item=>statusOf(item)==='Pending'&&item.id==='WS-AIDC-013');
 const closed=filtered.filter(item=>statusOf(item)!=='Pending');
 const toggle=(id:string)=>setChecked(current=>current.includes(id)?current.filter(item=>item!==id):[...current,id]);
 const BuildMark=({build}:{build:BuildState})=><span className={`inline-flex items-center gap-1 text-[9px] ${build==='Succeeded'?'text-emerald-700':build==='Failed'?'text-red-700':'text-amber-700'}`}>{build==='Succeeded'?<CheckCircle2 size={13}/>:build==='Failed'?<AlertTriangle size={13}/>:<Clock3 size={13}/>}<span>{build}</span></span>;
 const WorkspaceSection=({title,items,action}:{title:string;items:WorkspaceRecord[];action:string})=><section className="mb-5 overflow-hidden rounded-lg border border-slate-200 bg-white"><div className="flex items-center justify-between border-b border-slate-200 bg-slate-50/70 px-4 py-2.5"><div className="flex items-center gap-2"><h2 className="text-[10px] font-semibold text-slate-700">{title}</h2><span className="rounded-full bg-slate-200 px-1.5 py-0.5 text-[8px] text-slate-600">{items.length}</span></div><button disabled={!items.some(item=>checked.includes(item.id))} className="rounded border border-slate-200 bg-white px-2.5 py-1.5 text-[8px] font-medium text-slate-500 disabled:cursor-not-allowed disabled:opacity-40">{action}</button></div><div className="overflow-auto"><table className="w-full min-w-[820px] table-fixed text-left text-[9px]"><colgroup><col className="w-[4%]"/><col className="w-[26%]"/><col className="w-[11%]"/><col className="w-[12%]"/><col className="w-[16%]"/><col className="w-[16%]"/><col className="w-[15%]"/></colgroup><thead className="border-b border-slate-100 text-slate-400"><tr><th className="w-10 px-3 py-2"></th>{['Name','Status','Build','Created By','Modified By','Last Modified'].map(header=><th key={header} className="px-3 py-2 font-semibold">{header}</th>)}</tr></thead><tbody className="divide-y divide-slate-100">{items.map(item=><tr key={item.id} onClick={()=>setReviewId(item.id)} className="cursor-pointer hover:bg-blue-50/40"><td className="px-3 py-2.5" onClick={event=>event.stopPropagation()}><input type="checkbox" checked={checked.includes(item.id)} onChange={()=>toggle(item.id)} className="h-3 w-3 accent-blue-600"/></td><td className="px-3 py-2.5"><button onClick={()=>setReviewId(item.id)} className="text-left"><span className="block font-medium text-blue-600 hover:underline">{item.name}</span><span className="font-mono text-[8px] text-slate-400">{item.id}</span></button></td><td className="px-3 py-2.5"><StatePill value={statusOf(item)}/></td><td className="px-3 py-2.5"><BuildMark build={item.build}/></td><td className="px-3 py-2.5 text-slate-600">{item.owner}</td><td className="px-3 py-2.5 text-slate-600">{modifiedBy[item.id]||item.owner}</td><td className="px-3 py-2.5 text-slate-400">{item.updated}</td></tr>)}</tbody></table>{!items.length&&<div className="py-8 text-center text-[9px] text-slate-400">No workspaces in this section.</div>}</div></section>;
 if(reviewId){
  const selected=lifecycleWorkspaces.find(item=>item.id===reviewId)||lifecycleWorkspaces[0];
  const status=statusOf(selected); const canSubmit=status==='Pending'&&selected.build==='Succeeded'&&!selected.errors&&!selected.conflicts;
  const stages=[{name:'Input Validation',failed:selected.errors>0},{name:'Configlet Compilation',failed:selected.build==='Failed'},{name:'Config Validation',failed:selected.conflicts>0||selected.build==='Failed'}];
  const proposedDevices=Array.from({length:Math.min(Math.max(selected.devices,1),AIDC_LIFECYCLE_DEVICE_NAMES.length)},(_,index)=>({id:`${selected.id}-DEV-${index+1}`,name:AIDC_LIFECYCLE_DEVICE_NAMES[index]||`AIDC-Device-${String(index+1).padStart(2,'0')}`,added:index===AIDC_FABRIC_01.mappedDevices-1?0:28-index*3,removed:index===AIDC_FABRIC_01.mappedDevices-1?0:Math.max(0,4-index),unchanged:index===AIDC_FABRIC_01.mappedDevices-1}));
  return <Page><div className="mb-5 flex items-start justify-between"><div><button onClick={()=>{setReviewId(null);setExpandedDevice(null)}} className="mb-2 text-[9px] font-medium text-blue-600 hover:underline">‹ Workspaces</button><div className="flex items-center gap-2"><h1 className="text-2xl font-semibold text-slate-900">{selected.name}</h1><StatePill value={status}/></div><p className="mt-1 font-mono text-[9px] text-slate-400">{selected.id}</p><p className="mt-1 text-xs text-slate-500">{descriptions[selected.id]}</p><p className="mt-2 text-[9px] text-slate-400">Created by {selected.owner} · Modified by {modifiedBy[selected.id]||selected.owner} · {selected.updated}</p></div><div className="flex items-center gap-2">{status==='Pending'&&<button className="rounded-lg border border-slate-200 bg-white px-3 py-2.5 text-[10px] font-medium text-slate-600">Abandon</button>}<button disabled={status==='Pending'&&!canSubmit} className="rounded-lg bg-blue-600 px-4 py-2.5 text-[10px] font-semibold text-white disabled:cursor-not-allowed disabled:bg-slate-300">{status==='Submitted'?'View Change Control':'Submit Workspace'}</button></div></div>{status==='Pending'&&!canSubmit&&<div className="mb-4 flex items-center gap-2 rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-[9px] text-amber-700"><AlertTriangle size={13}/>Submission is available after the current Workspace Build completes without blocking errors or conflicts.</div>}<div className="mb-4 grid grid-cols-[1fr_1.15fr] overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm"><section className="border-r border-slate-200 p-5"><div className="mb-4 flex items-center justify-between"><h2 className="text-xs font-semibold text-slate-800">Summary</h2><button className="text-[9px] font-medium text-blue-600">View All Modification Details</button></div><div className="mb-3 grid grid-cols-[1fr_120px] border-b border-slate-100 pb-2 text-[8px] font-semibold text-slate-400"><span>Studios Modified</span><span>Modification Type</span></div><div className="space-y-2">{selected.sources.map(source=><div key={source.name} className="grid grid-cols-[1fr_120px] items-center text-[9px]"><span className="font-medium text-blue-600">{source.name}</span><span className="text-slate-500">{source.kind==='Foundation'?'Inventory / Connections':source.kind==='Advanced source'?'Advanced configuration':'Inputs / Assignments'}</span></div>)}</div><div className="mt-5 flex items-center justify-between border-t border-slate-100 pt-4 text-[9px]"><span className="text-slate-500">Number of Tag Changes</span><b className="text-slate-700">{selected.id==='WS-AIDC-018'?6:selected.id==='WS-AIDC-021'?4:0}</b></div></section><section className="p-5"><div className="mb-5 flex items-start justify-between"><div><h2 className="text-xs font-semibold text-slate-800">Build Status</h2><p className="mt-1 text-[8px] text-slate-400">Last run {selected.updated}</p></div><button className="text-[9px] font-medium text-blue-600">View Build Details</button></div><div className="flex items-start">{stages.map((stage,index)=>{const failed=stage.failed;const pending=selected.build==='Outdated';return <React.Fragment key={stage.name}><div className="flex w-28 flex-shrink-0 flex-col items-center text-center"><span className={`flex h-11 w-11 items-center justify-center rounded-full border-2 ${failed?'border-red-400 bg-red-50 text-red-600':pending?'border-amber-300 bg-amber-50 text-amber-600':'border-emerald-400 bg-emerald-50 text-emerald-600'}`}>{failed?<AlertTriangle size={18}/>:pending?<Clock3 size={18}/>:<CheckCircle2 size={18}/>}</span><span className="mt-2 text-[8px] font-medium text-slate-600">{stage.name}</span>{stage.name==='Configlet Compilation'&&!failed&&!pending&&<span className="mt-1 rounded-full bg-slate-100 px-2 py-0.5 text-[7px] text-slate-500">3 unchanged devices</span>}</div>{index<stages.length-1&&<div className={`mt-5 h-0.5 flex-1 ${failed?'bg-red-200':pending?'bg-amber-200':'bg-emerald-300'}`}/>}</React.Fragment>})}</div></section></div><section className="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm"><div className="flex items-center justify-between border-b border-slate-200 px-5 py-3"><div><h2 className="text-xs font-semibold text-slate-800">Proposed Configuration Changes</h2><p className="mt-1 text-[8px] text-slate-400">Review device-level differences before submitting this Workspace.</p></div><span className="text-[9px] text-slate-400">{selected.devices} affected devices</span></div><div className="divide-y divide-slate-100">{proposedDevices.map(device=><div key={device.id}><button onClick={()=>setExpandedDevice(expandedDevice===device.id?null:device.id)} className="flex w-full items-center justify-between px-5 py-3 text-left hover:bg-slate-50"><span><b className="block text-[10px] text-slate-700">{device.name}</b><span className="text-[8px] text-slate-400">Designed configuration compared with the device running configuration</span></span>{device.unchanged?<span className="text-[9px] text-slate-400">No configuration changes</span>:<span className="font-mono text-[9px]"><i className="not-italic text-emerald-600">+{device.added}</i><i className="ml-2 not-italic text-red-600">-{device.removed}</i></span>}</button>{expandedDevice===device.id&&!device.unchanged&&<div className="grid grid-cols-2 border-t border-slate-200 bg-white"><section className="border-r border-slate-200"><div className="flex items-center justify-between border-b border-slate-200 bg-slate-50 px-4 py-2"><span className="text-[9px] font-semibold text-slate-700">Designed Configuration</span><span className="text-[8px] text-slate-400">Proposed by this Workspace</span></div><div className="font-mono text-[9px] leading-5"><div className="grid grid-cols-[36px_1fr] bg-emerald-50 text-emerald-800"><span className="select-none border-r border-emerald-100 px-2 text-right text-emerald-400">24</span><span className="px-3">interface Ethernet33</span></div><div className="grid grid-cols-[36px_1fr] bg-emerald-50 text-emerald-800"><span className="select-none border-r border-emerald-100 px-2 text-right text-emerald-400">25</span><span className="px-3">  description GPU-NODE-17</span></div><div className="grid grid-cols-[36px_1fr] bg-emerald-50 text-emerald-800"><span className="select-none border-r border-emerald-100 px-2 text-right text-emerald-400">26</span><span className="px-3">  mtu 9214</span></div><div className="grid grid-cols-[36px_1fr] text-slate-600"><span className="select-none border-r border-slate-100 px-2 text-right text-slate-300">27</span><span className="px-3">  no shutdown</span></div></div></section><section><div className="flex items-center justify-between border-b border-slate-200 bg-slate-50 px-4 py-2"><span className="text-[9px] font-semibold text-slate-700">Running Configuration</span><span className="text-[8px] text-slate-400">Currently on {device.name}</span></div><div className="font-mono text-[9px] leading-5"><div className="grid grid-cols-[36px_1fr] text-slate-600"><span className="select-none border-r border-slate-100 px-2 text-right text-slate-300">38</span><span className="px-3">interface Ethernet33</span></div><div className="grid grid-cols-[36px_1fr] bg-red-50 text-red-800"><span className="select-none border-r border-red-100 px-2 text-right text-red-400">39</span><span className="px-3">  description AVAILABLE</span></div><div className="grid grid-cols-[36px_1fr] bg-red-50 text-red-800"><span className="select-none border-r border-red-100 px-2 text-right text-red-400">40</span><span className="px-3">  mtu 1500</span></div><div className="grid grid-cols-[36px_1fr] bg-red-50 text-red-800"><span className="select-none border-r border-red-100 px-2 text-right text-red-400">41</span><span className="px-3">  shutdown</span></div></div></section></div>}</div>)}</div></section></Page>
 }
 return <Page><LifecycleHeader kind="workspaces" title="Workspaces" subtitle="View the open and closed workspaces in your network." action="Create Workspace"/><div className="mb-4 flex items-center justify-between rounded-lg border border-slate-200 bg-white p-3 shadow-sm"><div className="w-96"><SearchBar value={query} onChange={setQuery} placeholder="Search workspaces"/></div><span className="text-[9px] text-slate-400">Showing {filtered.length} workspaces</span></div><WorkspaceSection title="Your Open Workspaces" items={yourOpen} action="Abandon Workspaces"/><WorkspaceSection title="Other Open Workspaces" items={otherOpen} action="Abandon Workspaces"/><WorkspaceSection title="Closed Workspaces" items={closed} action="Delete Workspaces"/></Page>
};

const TasksPage=()=>{const [query,setQuery]=useState('');const [selectedId,setSelectedId]=useState(lifecycleTasks[0].id);const [tab,setTab]=useState('Summary');const rows=lifecycleTasks.filter(item=>`${item.id} ${item.device} ${item.workspaceId} ${item.operation} ${item.source}`.toLowerCase().includes(query.toLowerCase()));const selected=lifecycleTasks.find(item=>item.id===selectedId)||lifecycleTasks[0];const taskCount=(state:TaskState)=>lifecycleTasks.filter(item=>item.state===state).length;return <Page><LifecycleHeader kind="tasks" title="Tasks" subtitle="Device-level execution work orders generated from submitted Workspaces."/><div className="mb-5 grid grid-cols-4 gap-3"><Metric label="Pending" value={String(taskCount('Pending'))} note="Awaiting Change Control approval" icon={<Clock3 size={15}/>}/><Metric label="Scheduled" value={String(taskCount('Scheduled'))} note="Included in the AIDC execution plan" icon={<Activity size={15}/>}/><Metric label="Running" value={String(taskCount('Running'))} note="Currently executing" icon={<RefreshCw size={15}/>}/><Metric label="Failed" value={String(taskCount('Failed'))} note="Requires investigation or remediation" icon={<AlertTriangle size={15}/>}/></div><div className="mb-4 flex items-center gap-2 rounded-lg border border-blue-200 bg-blue-50 px-3 py-2 text-[9px] text-blue-700"><ShieldCheck size={13}/>Tasks cannot execute directly. Every device-affecting Task must be orchestrated and executed through Change Control.</div><div className="grid grid-cols-[minmax(620px,1.35fr)_minmax(360px,0.65fr)] overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm"><section className="min-w-0 border-r border-slate-200"><div className="flex items-center gap-2 border-b border-slate-100 p-3"><SearchBar value={query} onChange={setQuery} placeholder="Search tasks, devices, workspaces or sources"/><button className="flex items-center gap-1 rounded-lg border border-slate-200 px-3 py-2.5 text-[9px] text-slate-500"><SlidersHorizontal size={12}/>Filters</button></div><div className="overflow-auto"><table className="w-full min-w-[720px] text-left text-[9px]"><thead className="bg-slate-50 text-slate-400"><tr>{['Task','Device','Workspace','Operation','Diff','State','Change Control'].map(header=><th key={header} className="px-3 py-2.5 font-semibold">{header}</th>)}</tr></thead><tbody className="divide-y divide-slate-100">{rows.map(item=><tr key={item.id} onClick={()=>{setSelectedId(item.id);setTab('Summary')}} className={`cursor-pointer ${selected.id===item.id?'bg-blue-50/70':'hover:bg-slate-50'}`}><td className="px-3 py-3 font-mono font-semibold text-blue-600">{item.id}</td><td className="px-3 py-3 font-medium text-slate-700">{item.device}</td><td className="px-3 py-3 font-mono text-slate-500">{item.workspaceId}</td><td className="px-3 py-3 text-slate-600">{item.operation}</td><td className="px-3 py-3 font-mono text-slate-500">{item.diff}</td><td className="px-3 py-3"><StatePill value={item.state}/></td><td className="px-3 py-3 font-mono text-slate-500">{item.controlId||'Not assigned'}</td></tr>)}</tbody></table>{!rows.length&&<EmptyRows message="No tasks match the current search."/>}</div></section><aside className="min-w-0"><div className="flex items-start justify-between gap-3 p-4"><div><div className="flex items-center gap-2"><h2 className="font-mono text-sm font-semibold text-slate-900">{selected.id}</h2><StatePill value={selected.state}/></div><p className="mt-1 text-[9px] text-slate-500">{selected.operation} · {selected.device}</p></div>{!selected.controlId&&<button className="rounded-md bg-blue-600 px-3 py-2 text-[9px] font-semibold text-white">Add to Change Control</button>}</div><DetailTabs items={['Summary','Configuration Diff','Dependencies','Execution','Audit']} value={tab} onChange={setTab}/><div className="max-h-[460px] overflow-auto p-4">{tab==='Summary'&&<><div className="rounded-lg border border-slate-200 px-3"><Pair label="Device" value={selected.device}/><Pair label="Source Workspace" value={selected.workspaceId} mono/><Pair label="Configuration source" value={selected.source}/><Pair label="Diff summary" value={selected.diff} mono/><Pair label="Change Control" value={selected.controlId||'Not assigned'} mono/></div><p className="mt-3 rounded-lg bg-slate-50 p-3 text-[9px] leading-4 text-slate-500">This Task is an immutable execution work order. Configuration design changes must be made in a new or open Workspace.</p></>}{tab==='Configuration Diff'&&<pre className="overflow-auto rounded-lg bg-slate-900 p-4 text-[9px] leading-5 text-slate-200"><span className="text-emerald-400">+ interface Ethernet33</span>{'\n'}<span className="text-emerald-400">+   service-profile ROCE-400G</span>{'\n'}<span className="text-red-400">-   service-profile DEFAULT</span></pre>}{tab==='Dependencies'&&<><Pair label="Previous stage" value="Pre-change validation"/><Pair label="Current stage" value={selected.controlId?'Device configuration':'Not assigned'}/><Pair label="Execution order" value={selected.controlId?'Stage 2 of 4':'Determined by Change Control'}/></>}{tab==='Execution'&&<><Pair label="Execution state" value={<StatePill value={selected.state}/>}/><Pair label="Started" value={selected.state==='Succeeded'||selected.state==='Failed'?'Yesterday 23:06':'Not started'}/><Pair label="Result" value={selected.state==='Failed'?'Device rejected configuration':selected.state==='Succeeded'?'Configuration applied':'Awaiting Change Control'}/></>}{tab==='Audit'&&<div className="space-y-3 text-[9px]"><p><span className="text-slate-400">Created:</span> Workspace {selected.workspaceId} submission</p><p><span className="text-slate-400">Source:</span> {selected.source}</p><p><span className="text-slate-400">Updated:</span> {selected.updated}</p></div>}</div></aside></div></Page>};

const ChangeControlPage=()=>{const [query,setQuery]=useState('');const [selectedId,setSelectedId]=useState(lifecycleControls[0].id);const [tab,setTab]=useState('Overview');const rows=lifecycleControls.filter(item=>`${item.id} ${item.name} ${item.workspaceId} ${item.owner}`.toLowerCase().includes(query.toLowerCase()));const selected=lifecycleControls.find(item=>item.id===selectedId)||lifecycleControls[0];return <Page><LifecycleHeader kind="change-control" title="Change Control" subtitle="Approve, schedule, orchestrate and audit every device-affecting Task." action="Create Change Control"/><div className="mb-5 grid grid-cols-4 gap-3"><Metric label="Awaiting approval" value={String(lifecycleControls.filter(item=>item.state==='Awaiting Approval').length)} note="Requires an authorized approver" icon={<ShieldCheck size={15}/>}/><Metric label="Scheduled" value={String(lifecycleControls.filter(item=>item.state==='Scheduled').length)} note="Ready for a maintenance window" icon={<Clock3 size={15}/>}/><Metric label="Running" value={String(lifecycleControls.filter(item=>item.state==='Running').length)} note="Active execution plans" icon={<Activity size={15}/>}/><Metric label="Needs attention" value={String(lifecycleControls.filter(item=>item.state==='Partially Failed').length)} note="Failed or partially failed" icon={<AlertTriangle size={15}/>}/></div><div className="grid grid-cols-[minmax(620px,1.35fr)_minmax(360px,0.65fr)] overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm"><section className="min-w-0 border-r border-slate-200"><div className="flex items-center gap-2 border-b border-slate-100 p-3"><SearchBar value={query} onChange={setQuery} placeholder="Search change controls, workspaces or owners"/><button className="flex items-center gap-1 rounded-lg border border-slate-200 px-3 py-2.5 text-[9px] text-slate-500"><SlidersHorizontal size={12}/>State</button></div><div className="overflow-auto"><table className="w-full min-w-[740px] text-left text-[9px]"><thead className="bg-slate-50 text-slate-400"><tr>{['Change Control','Source Workspace','Tasks','Devices','Stages','Approval / Schedule','Progress','State'].map(header=><th key={header} className="px-3 py-2.5 font-semibold">{header}</th>)}</tr></thead><tbody className="divide-y divide-slate-100">{rows.map(item=><tr key={item.id} onClick={()=>{setSelectedId(item.id);setTab('Overview')}} className={`cursor-pointer ${selected.id===item.id?'bg-blue-50/70':'hover:bg-slate-50'}`}><td className="px-3 py-3"><b className="block text-[10px] text-slate-800">{item.name}</b><span className="font-mono text-[8px] text-blue-600">{item.id}</span></td><td className="px-3 py-3 font-mono text-slate-500">{item.workspaceId}</td><td className="px-3 py-3 text-slate-600">{item.tasks}</td><td className="px-3 py-3 text-slate-600">{item.devices}</td><td className="px-3 py-3 text-slate-600">{item.stages}</td><td className="px-3 py-3"><span className="block text-slate-600">{item.approval}</span><span className="text-[8px] text-slate-400">{item.schedule}</span></td><td className="px-3 py-3 font-mono text-slate-500">{item.progress}</td><td className="px-3 py-3"><StatePill value={item.state}/></td></tr>)}</tbody></table>{!rows.length&&<EmptyRows message="No change controls match the current search."/>}</div></section><aside className="min-w-0"><div className="flex items-start justify-between gap-3 p-4"><div className="min-w-0"><div className="flex items-center gap-2"><h2 className="truncate text-sm font-semibold text-slate-900">{selected.name}</h2><StatePill value={selected.state}/></div><p className="mt-1 font-mono text-[8px] text-slate-400">{selected.id}</p></div>{selected.state==='Awaiting Approval'&&<button className="rounded-md bg-blue-600 px-3 py-2 text-[9px] font-semibold text-white">Review approval</button>}</div><DetailTabs items={['Overview','Tasks','Execution Plan','Approval','Execution','Audit']} value={tab} onChange={setTab}/><div className="max-h-[460px] overflow-auto p-4">{tab==='Overview'&&<><div className="rounded-lg border border-slate-200 px-3"><Pair label="Source Workspace" value={selected.workspaceId} mono/><Pair label="Owner" value={selected.owner}/><Pair label="Tasks / Devices" value={`${selected.tasks} / ${selected.devices}`}/><Pair label="Stages" value={String(selected.stages)}/><Pair label="Schedule" value={selected.schedule}/><Pair label="Progress" value={selected.progress}/></div><div className="mt-3 rounded-lg bg-blue-50 p-3 text-[9px] leading-4 text-blue-700">Tasks are immutable execution inputs. Approval, scheduling and stage orchestration are owned by this Change Control.</div></>}{tab==='Tasks'&&<div className="space-y-2">{lifecycleTasks.filter(task=>task.controlId===selected.id).map(task=><div key={task.id} className="flex items-center justify-between rounded-lg border border-slate-200 p-3"><span><b className="block font-mono text-[9px] text-blue-600">{task.id}</b><span className="text-[8px] text-slate-500">{task.device} · {task.operation}</span></span><StatePill value={task.state}/></div>)}{!lifecycleTasks.some(task=>task.controlId===selected.id)&&<EmptyRows message="Task details are not loaded for this Change Control."/>}</div>}{tab==='Execution Plan'&&<div className="space-y-2">{[['Stage 1','Pre-change validation','Reachability and configuration readiness'],['Stage 2','Spine devices','Execute in parallel'],['Stage 3','Leaf devices','Batched device configuration'],['Stage 4','Post-change verification','Compliance and connectivity checks']].slice(0,selected.stages).map(([stage,name,note],index)=><div key={stage} className="flex gap-3 rounded-lg border border-slate-200 p-3"><span className="flex h-6 w-6 flex-shrink-0 items-center justify-center rounded-full bg-slate-100 text-[9px] font-bold text-slate-600">{index+1}</span><span><b className="block text-[9px] text-slate-700">{name}</b><span className="text-[8px] text-slate-400">{note}</span></span></div>)}</div>}{tab==='Approval'&&<><Pair label="Decision" value={selected.state==='Awaiting Approval'?'Pending':'Approved'}/><Pair label="Approver" value={selected.state==='Awaiting Approval'?'Network Approver group':'Jordan Lee'}/><Pair label="Requested by" value={selected.owner}/><Pair label="Policy" value="Creator and approver separation"/><p className="mt-3 rounded-lg border border-amber-200 bg-amber-50 p-3 text-[9px] leading-4 text-amber-700">Changes to the Task set, device scope or execution plan invalidate the existing approval.</p></>}{tab==='Execution'&&<><Pair label="State" value={<StatePill value={selected.state}/>}/><Pair label="Progress" value={selected.progress}/><Pair label="Current stage" value={selected.state==='Completed'?'Post-change verification':selected.state==='Partially Failed'?'Device configuration':'Not started'}/><Pair label="Failed Tasks" value={selected.state==='Partially Failed'?'1':'0'}/><p className="mt-3 text-[9px] leading-4 text-slate-500">Rollback is handled as a separately approved remediation or compensating Change Control, preserving a complete audit trail.</p></>}{tab==='Audit'&&<div className="space-y-3 text-[9px]">{[['Created',`${selected.owner} · Yesterday 15:42`],['Tasks added',`${selected.tasks} Tasks from ${selected.workspaceId}`],['Approval',selected.approval],['Schedule',selected.schedule]].map(([label,value])=><div key={label} className="flex gap-3"><span className="w-20 flex-shrink-0 text-slate-400">{label}</span><span className="text-slate-600">{value}</span></div>)}</div>}</div></aside></div></Page>};

const DataPage=({kind,initialWorkspaceId}:{kind:LifecycleKind;initialWorkspaceId?:string})=>kind==='workspaces'?<WorkspacesPage initialWorkspaceId={initialWorkspaceId}/>:kind==='tasks'?<TasksPage/>:<ChangeControlPage/>;
const AIDCProvisioning: React.FC<Props> = ({site,feature,initialWorkspaceId}) => { const [selectedStudio,setSelectedStudio]=useState<Studio|null>(null); if(feature==='studios') return selectedStudio?(selectedStudio.id==='STD-ESS-001'?<AIDCInventoryTopology onBack={()=>setSelectedStudio(null)}/>:<StructuredStudio studio={selectedStudio} onBack={()=>setSelectedStudio(null)}/>):<StudiosList site={site} onOpen={setSelectedStudio}/>; if(feature==='workspaces') return <DataPage kind="workspaces" initialWorkspaceId={initialWorkspaceId}/>; if(feature==='tasks') return <DataPage kind="tasks"/>; return <DataPage kind="change-control"/> };
export default AIDCProvisioning;